{"code": "from collections import deque
lines = current_frame.ascii.split('\n')
grid = [list(r) for r in lines]
R,C = len(grid), len(grid[0])
from collections import Counter
print(Counter(c for r in grid for c in r))
# S mask
S = [[grid[r][c]=='S' for c in range(C)] for r in range(R)]
seen=[[False]*C for _ in range(R)]
comps=[]
for r in range(R):
    for c in range(C):
        if S[r][c] and not seen[r][c]:
            q=deque([(r,c)]); seen[r][c]=True; cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<R and 0<=ny<C and S[nx][ny] and not seen[nx][ny]:
                        seen[nx][ny]=True; q.append((nx,ny))
            comps.append(cells)
for i,cells in enumerate(comps):
    rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
    print(i, len(cells), min(rs),max(rs),min(cs),max(cs))
"}

